<?php
require $_SERVER['DOCUMENT_ROOT'].'/main.inc.php';
require_once __DIR__.'/../lib/main.lib.php';
require_once __DIR__.'/../class/InternalTaskCollaborationService.class.php';
cpo_task_require($db,$user);$langs->load('chinaplanetoperations@chinaplanetoperations');$service=new InternalTaskCollaborationService($db,$user);
try{$rows=$service->inbox(GETPOST('cursor_date','alphanohtml'),GETPOSTINT('cursor_id'));$unread=$service->unreadCount();}catch(Throwable $e){accessforbidden();}
if(GETPOSTINT('inbox_page')===1){$payload=array();foreach($rows as $row){$author=trim($row['author_firstname'].' '.$row['author_lastname']);if($author==='')$author=$row['author_login']?:$langs->trans('InternalTaskFormerUser');$payload[]=array('id'=>(int)$row['rowid'],'task_id'=>(int)$row['fk_task'],'task_ref'=>$row['task_ref'],'author'=>$author,'created'=>dol_print_date($db->jdate($row['date_creation']),'dayhour'),'cursor_date'=>$row['date_creation'],'unread'=>empty($row['date_seen']));}header('Content-Type: application/json; charset=utf-8');header('Cache-Control: private, no-store');echo json_encode(array('ok'=>true,'notifications'=>$payload,'has_older'=>count($rows)===50,'token'=>newToken(),'mentioned'=>$langs->trans('InternalTaskMentionedYou'),'open'=>$langs->trans('Open')),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$db->close();exit;}
$morecss=array(cpo_asset('/custom/chinaplanetoperations/css/operations.css'));$morejs=array(cpo_asset('/custom/chinaplanetoperations/js/internal_tasks.js'));llxHeader('',$langs->trans('InternalTaskNotifications'),'','',0,0,$morejs,$morecss);
?>
<?php $oldestNotification=$rows?$rows[count($rows)-1]:null; ?><template id="cpo-inbox-page-meta" data-has-older="<?php echo count($rows)===50?'1':'0'; ?>" data-cursor-date="<?php echo dol_escape_htmltag($oldestNotification?$oldestNotification['date_creation']:''); ?>" data-cursor-id="<?php echo (int)($oldestNotification?$oldestNotification['rowid']:0); ?>" data-load="<?php echo dol_escape_htmltag($langs->trans('InternalTaskLoadOlder')); ?>" data-loading="<?php echo dol_escape_htmltag($langs->trans('InternalTaskLoading')); ?>" data-error="<?php echo dol_escape_htmltag($langs->trans('InternalTaskLoadFailed')); ?>"></template>
<main class="cpo-page cpo-task-inbox"><section class="cpo-hero"><div><span class="cpo-eyebrow"><?php echo $langs->trans('TeamTasks'); ?></span><h1><?php echo $langs->trans('InternalTaskNotifications'); ?></h1><p><?php echo $langs->trans('InternalTaskUnreadCount',$unread); ?></p></div><a class="button" href="board.php"><?php echo $langs->trans('Back'); ?></a></section>
<section class="cpo-panel"><div class="cpo-panel-head"><h2><?php echo $langs->trans('InternalTaskMentions'); ?></h2></div><?php if(!$rows){ ?><p class="cpo-empty-state"><?php echo $langs->trans('InternalTaskNoNotifications'); ?></p><?php }else{ ?><div class="cpo-notification-list"><?php foreach($rows as $row){$author=trim($row['author_firstname'].' '.$row['author_lastname']);if($author==='')$author=$row['author_login']?:$langs->trans('InternalTaskFormerUser'); ?><article class="cpo-notification<?php echo empty($row['date_seen'])?' is-unread':''; ?>"><div><strong><bdi dir="auto"><?php echo dol_escape_htmltag($author); ?></bdi></strong> <?php echo $langs->trans('InternalTaskMentionedYou'); ?> <bdi><?php echo dol_escape_htmltag($row['task_ref']); ?></bdi><small><?php echo dol_escape_htmltag(dol_print_date($db->jdate($row['date_creation']),'dayhour')); ?></small></div><form method="post" action="collaboration_action.php"><input type="hidden" name="token" value="<?php echo newToken(); ?>"><input type="hidden" name="action" value="notification_read"><input type="hidden" name="task_id" value="<?php echo (int)$row['fk_task']; ?>"><input type="hidden" name="notification_id" value="<?php echo (int)$row['rowid']; ?>"><button class="button"><?php echo $langs->trans('Open'); ?></button></form></article><?php } ?></div><?php } ?></section></main>
<?php llxFooter();$db->close(); ?>
